<template>
  <div class="signup">
    <h2>Create Account</h2>
    <form @submit.prevent="signup" class="signup-form">
      <div class="form-group">
        <label for="name">Full Name</label>
        <input type="text" class="form-control" id="name" v-model="name" required>
      </div>
      
      <div class="form-group">
        <label for="email">Email address</label>
        <input type="email" class="form-control" id="email" v-model="email" required>
      </div>
      
      <div class="form-group">
        <label for="password">Password</label>
        <input type="password" class="form-control" id="password" v-model="password" required>
      </div>
      
      <button type="submit" class="btn btn-primary">Sign Up</button>
      
      <div class="divider">
        <span>OR</span>
      </div>
      
      <button type="button" @click="signInWithGoogle" class="btn btn-google">
        <img src="https://t3.gstatic.com/faviconV2?client=SOCIAL&type=FAVICON&fallback_opts=TYPE,SIZE,URL&url=http://google.com&size=128" alt="Google" class="google-icon">
        Sign up with Google
      </button>
      
      <p class="mt-3 text-center">
        Already have an account? 
        <router-link to="/login">Login</router-link>
      </p>
    </form>
  </div>
</template>

<script>
export default {
  data() {
    return {
      name: '',
      email: '',
      password: ''
    };
  },
  methods: {
    async signup() {
      try {
        await this.$store.dispatch('signUp', {
          email: this.email,
          password: this.password,
          name: this.name
        });
        this.$router.push('/');
      } catch (error) {
        console.error("Error signing up: ", error);
      }
    },
    async signInWithGoogle() {
      try {
        await this.$store.dispatch('signInWithGoogle');
        this.$router.push('/');
      } catch (error) {
        console.error("Error signing in with Google: ", error);
      }
    }
  }
}
</script>

